    // Make the original node the right child of the new root
    leftChild.right = node;

    // Update parent references if available
    try {
        if (node.parent != null) {
            if (node.parent.left == node) {
                node.parent.left = leftChild;
            } else if (node.parent.right == node) {
                node.parent.right = leftChild;
            }
            leftChild.parent = node.parent;
        } else {
            leftChild.parent = null;
        }
    } catch (NoSuchFieldError | IllegalAccessError ignored) {
        // No parent field; ignore
    }
    // The original node's parent is now the new root
    try {
        node.parent = leftChild;
    } catch (NoSuchFieldError | IllegalAccessError ignored) {
        // No parent field; ignore
    }

    // Return the new parent of the rotated node
    return leftChild;
}

private TreeNode<T> rotateRight(TreeNode<T> node){
    if (node == null) return null;
    TreeNode<T> left = node.left;
    if (left == null) return node;
    TreeNode<T> leftRight = left.right;

    // Perform rotation
    left.right = node;
    node.left = leftRight;

    // Update parent references
    TreeNode<T> parent = node.parent;
    node.parent = left;
    left.parent = parent;
    if (leftRight != null) leftRight.parent = node;

    // Reattach to original parent
    if (parent != null) {
        if (parent.left == node) {
            parent.left = left;
        } else if (parent.right == node) {
            parent.right = left;
        }
    }
    return left;
}

