        try {
            // Attempt to call getFormattedMessage via reflection for maximum compatibility.
            java.lang.reflect.Method fmtMethod = event.getClass().getMethod("getFormattedMessage");
            Object result = fmtMethod.invoke(event);
            if (result instanceof String) {
