            }
        } catch (NoSuchMethodException nsme) {
            // ignore and fallback to getMessage
        }
        return event.getMessage();
    } catch (Exception e) {
        // In case of any unexpected error, return an empty string rather than propagating the exception.
        return "";
    }
}

