private int parseEndOfLine(String headerPart, int end){
    if (headerPart == null) {
        throw new IllegalArgumentException("headerPart cannot be null");
    }
    if (end < 0 || end > headerPart.length()) {
        throw new IllegalArgumentException("end index out of bounds");
    }
    int idx = end;
    // Search for the CRLF sequence.
    while (idx < headerPart.length() - 1) {
        if (headerPart.charAt(idx) == '\r' && headerPart.charAt(idx + 1) == '\n') {
            return idx;
        }
        idx++;
    }
    // If not found, indicate failure with -1.
    return -1;
}

private int parseEndOfLine(String headerPart,int end){
    if (headerPart == null || end < 0) {
        return -1;
    }
    int length = headerPart.length();
    // Cannot find CRLF if there's less than two remaining characters
    if (length < 2) {
        return -1;
    }
    // Ensure the starting index does not exceed the bounds minus 1
    int start = Math.min(end, length - 2);
    for (int i = start; i < length - 1; i++) {
        if (headerPart.charAt(i) == '\r' && headerPart.charAt(i + 1) == '\n') {
            return i;
        }
    }
    return -1;
}

