public static <T> int writeDelimitedTo(OutputStream out, T message, Schema<T> schema, LinkedBuffer buffer) throws IOException {
    // Compute the size of the serialized message
    int size = 0;
    if (schema instanceof MessageLite) {
        size = ((MessageLite) schema).getSerializedSize(message);
    } else {
        // Fallback: use schema's writeTo method to a temporary buffer to get size
        LinkedBuffer tempBuffer = LinkedBuffer.allocate();
        schema.write(message, tempBuffer);
        size = tempBuffer.position();
    }

    // Write the length prefix as a varint
    for (int tmp = size; tmp > 0x7F; tmp >>>= 7) {
        out.write((tmp & 0x7F) | 0x80);
    }
    out.write(size);

    // Write the actual message
    schema.write(message, out, buffer);

    // Return the size of the message (not including the length prefix)
    return size;
}

public static <T>int writeDelimitedTo(OutputStream out,T message,Schema<T> schema,LinkedBuffer buffer) throws IOException {
    // Serialize the message to a byte array
    byte[] bytes = schema.toByteArray(message);
    int size = bytes.length;

    // Write the length of the message as a 4‑byte big‑endian integer
    out.write(java.nio.ByteBuffer.allocate(4).putInt(size).array());

    // Write the serialized message bytes
    out.write(bytes);

    return size;
}

public static <T> int writeDelimitedTo(OutputStream out, T message, Schema<T> schema, LinkedBuffer buffer) throws IOException {
    // clear the buffer before writing a new message
    buffer.clear();
    // serialize the message into the buffer
    schema.writeTo(message, buffer);
    // get the size of the serialized message
    int size = buffer.position();
    // write the length prefix (varint) to the output stream
    int varintSize = size;
    while ((varintSize & ~0x7F) != 0) {
        out.write((varintSize & 0x7F) | 0x80);
        varintSize >>>= 7;
    }
    out.write(varintSize);
    // write the actual message bytes
    out.write(buffer.array(), 0, size);
    // flush the stream to ensure all data is written
    out.flush();
    // return the size of the message (excluding the length prefix)
    return size;
}

