public synchronized void send(final String message) {
    if (message == null) {
        throw new IllegalArgumentException("message cannot be null");
    }
    for (Client client : clients) {
        try {
            client.sendTelnet(message);
        } catch (Exception e) {
            // swallow or log the exception per client to avoid halting the broadcast
        }
    }
}

public synchronized void send(final String message) {
    if (message == null) {
        return;
    }
    if (clients == null) {
        return;
    }
    String formatted = message + "\r\n";
    java.util.Iterator<OutputStream> it = clients.iterator();
    while (it.hasNext()) {
        OutputStream out = it.next();
        try {
            out.write(formatted.getBytes());
            out.flush();
        } catch (Exception e) {
            try {
                out.close();
            } catch (Exception ignored) {
            }
            it.remove();
        }
    }
}

public synchronized void send(final String message){
    if(message == null){
        return;
    }
    // Convert message to telnet-friendly line endings (CRLF)
    String telnetMsg = message.replaceAll("\\r?\\n", "\r\n");
    for(OutputStream os : clientStreams){
        try{
            os.write(telnetMsg.getBytes());
            os.flush();
        }catch(IOException e){
            // Ignore failed client, continue with others
        }
    }
}

