            if (buffer instanceof java.util.concurrent.BlockingQueue) {
                // `offer` returns false if the queue is full, so we silently drop
                ((java.util.concurrent.BlockingQueue<LoggingEvent>) buffer).offer(o);
            } else if (buffer instanceof java.util.Collection) {
                // For collections we try to add and rely on any exception or
