protected List<TimeRange> buildTimeRanges(long start, long end) {
    java.util.List<TimeRange> ranges = new java.util.ArrayList<>();
    // Ensure start <= end, swap if necessary
    if (start > end) {
        long tmp = start;
        start = end;
        end = tmp;
    }
    // Guard against non-positive FETCH_DATA_DURATION
    if (FETCH_DATA_DURATION <= 0) {
        throw new IllegalArgumentException("FETCH_DATA_DURATION must be positive");
    }
    long current = start;
    while (current < end) {
        long subEnd = Math.min(current + FETCH_DATA_DURATION, end);
        ranges.add(new TimeRange(current, subEnd));
        current = subEnd;
    }
    return ranges;
}

protected List<TimeRange> buildTimeRanges(long start, long end) {
    // Validate input ranges
    if (end < start) {
        throw new IllegalArgumentException("End time must be greater than or equal to start time");
    }
    if (FETCH_DATA_DURATION <= 0) {
        throw new IllegalArgumentException("FETCH_DATA_DURATION must be positive");
    }

    List<TimeRange> ranges = new ArrayList<>();
    long current = start;
    while (current < end) {
        // Calculate the end of the current sub-range
        long subEnd = Math.min(current + FETCH_DATA_DURATION, end);
        // Ensure we don't create a range where start == end
        if (current < subEnd) {
            ranges.add(new TimeRange(current, subEnd));
        }
        current = subEnd;
    }
    return ranges;
}

protected List<TimeRange> buildTimeRanges(long start,long end){
    if (FETCH_DATA_DURATION <= 0) {
        throw new IllegalArgumentException("FETCH_DATA_DURATION must be positive");
    }
    if (start >= end) {
        return new ArrayList<>();
    }
    List<TimeRange> ranges = new ArrayList<>();
    long s = start;
    while (s < end) {
        long e = s + FETCH_DATA_DURATION;
        if (e > end) {
            e = end;
        }
        ranges.add(new TimeRange(s, e));
        s = e;
    }
    return ranges;
}

protected List<TimeRange> buildTimeRanges(long start,long end){
    List<TimeRange> ranges = new ArrayList<>();
    if (start >= end) {
        return ranges;
    }
    long current = start;
    while (current < end) {
        long next = current + FETCH_DATA_DURATION;
        if (next > end) {
            next = end;
        }
        ranges.add(new TimeRange(current, next));
        current = next;
    }
    return ranges;
}

protected List<TimeRange> buildTimeRanges(long start,long end){
    List<TimeRange> ranges = new ArrayList<>();
    if (FETCH_DATA_DURATION <= 0 || start >= end) {
        return ranges;
    }
    long currentStart = start;
    while (currentStart < end) {
        long remaining = end - currentStart;
        long duration = remaining < FETCH_DATA_DURATION ? remaining : FETCH_DATA_DURATION;
        long currentEnd = currentStart + duration;
        if (currentEnd > end) {
            currentEnd = end;
        }
        ranges.add(new TimeRange(currentStart, currentEnd));
        currentStart = currentEnd;
    }
    return ranges;
}

