static long compressTimeBucket(long timeBucket,int dayStep){
    if(dayStep <= 0){
        throw new IllegalArgumentException("dayStep must be positive");
    }
    int year = (int)(timeBucket / 10000);
    int month = (int)((timeBucket % 10000) / 100);
    int day = (int)(timeBucket % 100);
    if(day < 1){
        throw new IllegalArgumentException("day must be >= 1");
    }
    int bucketDay = ((day - 1) / dayStep) * dayStep + 1;
    return year * 10000L + month * 100L + bucketDay;
}

static long compressTimeBucket(long timeBucket,int dayStep){
    if(dayStep <= 0){
        throw new IllegalArgumentException("dayStep must be positive");
    }
    long year = timeBucket / 10000;
    long month = (timeBucket % 10000) / 100;
    long day = timeBucket % 100;
    if(year <= 0 || month < 1 || month > 12 || day < 1 || day > 31){
        throw new IllegalArgumentException("Invalid time bucket format: " + timeBucket);
    }
    long newDay = ((day - 1) / dayStep) * dayStep + 1;
    return year * 10000 + month * 100 + newDay;
}

static long compressTimeBucket(long timeBucket,int dayStep){
