        throw new IllegalArgumentException("dayStep must be positive");
    }
    long year = timeBucket / 10000;
    int month = (int)((timeBucket % 10000) / 100);
    int day = (int)(timeBucket % 100);
    if(month < 1 || month > 12){
        throw new IllegalArgumentException("Invalid month in timeBucket: " + month);
    }
    int maxDay = java.time.YearMonth.of((int)year, month).lengthOfMonth();
    if(day < 1 || day > maxDay){
        throw new IllegalArgumentException("Invalid day in timeBucket: " + day);
    }
    int bucketStartDay = ((day - 1) / dayStep) * dayStep + 1;
    if(bucketStartDay > maxDay){
        bucketStartDay = maxDay;
    }
    return year * 10000L + month * 100L + bucketStartDay;
}

public static int computeUTF8Size(final CharSequence str, final int index, final int len) {
    if (str == null) {
        throw new NullPointerException("input string must not be null");
    }
    if (index < 0 || len < 0 || index + len > str.length()) {
        throw new IllegalArgumentException("index and len out of bounds");
    }
    int end = index + len;
    int total = 0;
    for (int i = index; i < end; ) {
        char ch = str.charAt(i++);
        if (ch <= 0x007F) {
            total += 1;
        } else if (ch <= 0x07FF) {
            total += 2;
        } else if (Character.isHighSurrogate(ch)) {
            if (i < end) {
                char lo = str.charAt(i);
                if (Character.isLowSurrogate(lo)) {
                    int codePoint = Character.toCodePoint(ch, lo);
                    i++;
                    if (codePoint <= 0xFFFF) {
                        total += 3;
                    } else {
                        total += 4;
                    }
                    continue;
                }
            }
            // Unpaired high surrogate, treat as replacement character U+FFFD
            total += 3;
        } else {
            // Low surrogate without preceding high surrogate or regular BMP char > 0x07FF
            if (Character.isLowSurrogate(ch)) {
                // Unpaired low surrogate, treat as replacement character U+FFFD
                total += 3;
            } else { // 0x0800 <= ch <= 0xFFFF
                total += 3;
            }
        }
    }
    return total;
}

