                if (Character.isLowSurrogate(low)) {  
                    total += 4;  
                    i++; // Skip low surrogate  
                    continue;  
                }  
            }  
            total += 3;  
        }  
    }  
    return total;  
}

public static int computeUTF8Size(final CharSequence str, final int index, final int len) {
    if (str == null) {
        throw new NullPointerException("str");
    }
    int total = str.length();
    if (index < 0 || len < 0 || index + len > total) {
        throw new IndexOutOfBoundsException("Invalid index or length");
    }
    int byteCount = 0;
    int end = index + len;
    for (int i = index; i < end; ) {
        char ch = str.charAt(i);
        int codePoint;
        if (Character.isHighSurrogate(ch)) {
            if (i + 1 < end) {
                char low = str.charAt(i + 1);
                if (Character.isLowSurrogate(low)) {
                    codePoint = Character.toCodePoint(ch, low);
                    i += 2;
                } else {
                    throw new IllegalArgumentException("Malformed surrogate pair at index " + i);
                }
            } else {
                throw new IllegalArgumentException("High surrogate without following low surrogate at index " + i);
            }
        } else if (Character.isLowSurrogate(ch)) {
            throw new IllegalArgumentException("Low surrogate without preceding high surrogate at index " + i);
        } else {
            codePoint = ch;
            i++;
        }
        if (codePoint <= 0x7F) {
            byteCount += 1;
        } else if (codePoint <= 0x7FF) {
            byteCount += 2;
        } else if (codePoint <= 0xFFFF) {
            byteCount += 3;
        } else {
            byteCount += 4;
        }
    }
    return byteCount;
}

