    int required = this.size + size;
    // If the current capacity is sufficient, no action is needed
    if (required <= this.capacity) {
        return;
    }
    // Determine the new capacity: double the current one, or at least the required amount
    int newCapacity = Math.max(this.capacity * 2, required);
    if (newCapacity == 0) { // handle the case where the vector is initially empty
        newCapacity = Math.max(16, required);
