    if (o1 == null) {
        return (o2 == null) ? 0 : -1;
    }
    if (o2 == null) {
        return 1;
    }
    int sign = Double.compare(o1, o2);
    return sign < 0 ? -1 : (sign > 0 ? 1 : 0);
}

