    if (o1 == null && o2 == null) {
        return 0;
    }
    if (o1 == null) {
        return -1;
    }
    if (o2 == null) {
        return 1;
    }
    try {
        int cmp = Double.compare(o1, o2);
        if (cmp < 0) {
            return -1;
        }
        if (cmp > 0) {
            return 1;
        }
        return 0;
    } catch (RuntimeException ex) {
        throw new RuntimeException("Comparison failed", ex);
    }
}

