private boolean containsAllFields(Fields fields){
    if(fields == null){
        return false;
    }
    try{
        // Attempt to retrieve a collection of field names via common method names
        Object namesObj = null;
        try{
            namesObj = fields.getClass().getMethod("getFieldNames").invoke(fields);
        }catch(NoSuchMethodException e){ /* ignore */ }
        try{
            if(namesObj == null){
                namesObj = fields.getClass().getMethod("getFields").invoke(fields);
            }
        }catch(NoSuchMethodException e){ /* ignore */ }
        if(namesObj instanceof java.util.Collection){
            for(Object nameObj : (java.util.Collection<?>)namesObj){
                if(!(nameObj instanceof String)){
                    continue;
                }
                String name = (String)nameObj;
                if(!properties.containsKey(name)){
                    return false;
                }
            }
            return true;
        }
        // Fallback: if Fields implements Map
        if(fields instanceof java.util.Map){
            java.util.Map<?,?> map = (java.util.Map<?,?>)fields;
            for(Object key : map.keySet()){
                if(!(key instanceof String)){
                    continue;
                }
                if(!properties.containsKey((String)key)){
                    return false;
                }
            }
            return true;
        }
    }catch(Exception e){
        // Any exception is treated as a failure to confirm presence
        return false;
    }
    return false;
}

