    try {
        if (fields == null) {
            return false;
        }
        // Assume a class-level collection that stores the known fields.
        if (properties == null) {
            return false;
        }
        return properties.contains(fields);
    } catch (Exception e) {
        // Swallow unexpected errors and indicate the fields were not found.
