public static int writeTo(final DataOutput out, LinkedBuffer node) throws IOException {
    if (out == null) {
        throw new NullPointerException("DataOutput cannot be null");
    }
    int totalSize = 0;
    LinkedBuffer current = node;
    while (current != null) {
        // Retrieve the byte array and the number of valid bytes in this node.
        byte[] data = current.getData();
        int length = current.getSize();
        // Write the valid bytes to the DataOutput.
        out.write(data, 0, length);
        totalSize += length;
        // Advance to the next node in the linked list.
        current = current.getNext();
    }
    return totalSize;
}

