    if (out == null) {
        throw new IllegalArgumentException("DataOutput must not be null");
    }
    if (node == null) {
        return 0;
    }
    int total = 0;
    LinkedBuffer current = node;
    while (current != null) {
        // The LinkedBuffer class provides direct access to its buffer and size.
        out.write(current.buf, 0, current.size);
        total += current.size;
        current = current.next;
    }
    return total;
}

