@Override protected Object convertToType(final Class<?> type,final Object value) throws Exception {
    if (type == null) {
        throw new IllegalArgumentException("Target type cannot be null");
    }
    if (type == Character.class || type == char.class) {
        if (value == null) {
            return null;
        }
        if (value instanceof Character) {
            return value;
        }
        if (value instanceof String) {
            String str = (String) value;
            if (str.length() == 1) {
                return str.charAt(0);
            } else {
                throw new Exception("String length must be 1 to convert to Character: " + str);
            }
        }
        if (value instanceof Number) {
            int intVal = ((Number) value).intValue();
            if (intVal >= Character.MIN_VALUE && intVal <= Character.MAX_VALUE) {
                return (char) intVal;
            } else {
                throw new Exception("Numeric value out of char range: " + intVal);
            }
        }
        throw new Exception("Unsupported value type for Character conversion: " + value.getClass().getName());
    }
    throw new Exception("Target type is not Character: " + type.getName());
}

