public static int nextPrime(int desiredCapacity){
    if (desiredCapacity <= 2) {
        return 2;
    }
    if (desiredCapacity == 3) {
        return 3;
    }
    int candidate = desiredCapacity;
    if ((candidate & 1) == 0) {
        candidate++; // ensure odd
    }
    while (candidate > 0) {
        int sqrt = (int)Math.sqrt(candidate);
        boolean isPrime = true;
        for (int i = 3; i <= sqrt; i += 2) {
            if (candidate % i == 0) {
                isPrime = false;
                break;
            }
        }
        if (isPrime) {
            return candidate;
        }
        candidate += 2;
    }
    // Fallback to the largest int if overflow occurs
    return Integer.MAX_VALUE - 1;
}

