        int limit = (int)Math.sqrt(n);
        for (int i = 2; i <= limit; i++) {
            if (n % i == 0) {
                isPrime = false;
                break;
            }
        }
        if (isPrime) {
            if (maxCap != 0 && n > maxCap) {
                // Ensure we return a prime within 11% if possible, otherwise accept the found prime
                return n;
            }
            return n;
        }
        n += 2; // skip even numbers
        if (n < 0) { // overflow protection
            throw new IllegalArgumentException("desiredCapacity too large for prime calculation");
        }
    }
