public static int nextPrime(int desiredCapacity) {
    if (desiredCapacity <= 2) {
        return 2;
    }
    int candidate = desiredCapacity;
    if (candidate % 2 == 0) {
        candidate++;
    }
    while (true) {
        boolean isPrime = true;
        int limit = (int) Math.sqrt(candidate);
        if (candidate % 2 == 0 && candidate != 2) {
            isPrime = false;
        } else {
            for (int i = 3; i <= limit; i += 2) {
                if (candidate % i == 0) {
                    isPrime = false;
                    break;
                }
            }
        }
        if (isPrime) {
            return candidate;
        }
        candidate += 2;
    }
}

public static int nextPrime(int desiredCapacity) {
    if (desiredCapacity < 2) {
        return 2;
    }
    // Guard against overflow: if desiredCapacity is close to Integer.MAX_VALUE,
    // we simply return the largest even prime we can safely represent.
    if (desiredCapacity > Integer.MAX_VALUE - 2) {
        return Integer.MAX_VALUE - 2; // 2147483647 is prime, but we avoid arithmetic overflow.
    }
    int candidate = desiredCapacity;
    // Ensure candidate starts at an odd number (except for 2 which is already handled).
    if ((candidate & 1) == 0) {
        candidate++;
    }
    while (true) {
        boolean isPrime = true;
        if (candidate <= 1) {
            isPrime = false;
        } else if (candidate <= 3) {
            isPrime = true;
        } else if ((candidate % 2) == 0 || (candidate % 3) == 0) {
            isPrime = false;
        } else {
            int limit = (int) Math.sqrt(candidate);
            for (int i = 5; i <= limit; i += 6) {
                if ((candidate % i) == 0 || (candidate % (i + 2)) == 0) {
                    isPrime = false;
                    break;
                }
            }
        }
        if (isPrime) {
            return candidate;
        }
        // Increment candidate to the next odd number.
        candidate += 2;
        // If candidate overflowed, return the maximum safe prime.
        if (candidate <= 0) {
            return Integer.MAX_VALUE - 2;
        }
    }
}

public static int nextPrime(int desiredCapacity) {
    int candidate = desiredCapacity;
    if (candidate < 2) candidate = 2;
    while (candidate >= 0) {
        boolean isPrime = true;
        if (candidate < 2) {
            isPrime = false;
        } else if (candidate == 2) {
            isPrime = true;
        } else if (candidate % 2 == 0) {
            isPrime = false;
        } else {
            int limit = (int) Math.sqrt(candidate);
            for (int i = 3; i <= limit; i += 2) {
                if (candidate % i == 0) {
                    isPrime = false;
                    break;
                }
            }
        }
        if (isPrime) return candidate;
        if (candidate == Integer.MAX_VALUE) return Integer.MAX_VALUE;
        candidate++;
    }
    return Integer.MAX_VALUE;
}

