public static String unescapeJava(String str) throws Exception {
    if (str == null) {
        return null;
    }
    StringBuilder sb = new StringBuilder();
    int len = str.length();
    for (int i = 0; i < len; i++) {
        char c = str.charAt(i);
        if (c == '\\') {
            if (i == len - 1) {
                throw new Exception("Trailing backslash at end of string");
            }
            char next = str.charAt(i + 1);
            switch (next) {
                case 'n':
                    sb.append('\n');
                    break;
                case 't':
                    sb.append('\t');
                    break;
                case 'b':
                    sb.append('\b');
                    break;
                case 'f':
                    sb.append('\f');
                    break;
                case 'r':
                    sb.append('\r');
                    break;
                case '\'':
                    sb.append('\'');
                    break;
                case '\"':
                    sb.append('\"');
                    break;
                case '\\':
                    sb.append('\\');
                    break;
                case 'u':
                    if (i + 6 > len) {
                        throw new Exception("Incomplete unicode escape sequence");
                    }
                    String hex = str.substring(i + 2, i + 6);
                    try {
                        int code = Integer.parseInt(hex, 16);
                        sb.append((char) code);
                    } catch (NumberFormatException e) {
                        throw new Exception("Invalid unicode escape sequence: \\u" + hex);
                    }
                    i += 5; // skip 'u' and four hex digits; loop will +1 more
                    continue;
                default:
                    throw new Exception("Unsupported escape sequence: \\" + next);
            }
            i++; // skip the escape character
        } else {
            sb.append(c);
        }
    }
    return sb.toString();
}

