    // Iterate over a snapshot of the list to avoid concurrent modification exceptions
    for (Category child : new ArrayList<>(childList)) {
        try {
            // Recursively remove unused nodes in the subtree
            removedCount += child.removeUnusedNodes();
            // After recursive cleanup, determine whether this child should be removed
            boolean isInactive = !child.isActive();
            boolean hasAnyChildren = child.getChildren() != null && !child.getChildren().isEmpty();
            if (isInactive && !hasAnyChildren) {
                if (childList.remove(child)) {
                    removedCount++;
                }
            }
        } catch (Exception e) {
