    if (root == null) {
        return 0;
    }
    int removedCount = 0;
    // Use a stack to perform a depth‑first traversal of the tree.
    java.util.List<Category> stack = new java.util.ArrayList<>();
    stack.add(root);
    while (!stack.isEmpty()) {
        Category current = stack.remove(stack.size() - 1);
        java.util.List<Category> children = current.getChildren();
        if (children == null || children.isEmpty()) {
            continue;
        }
        java.util.Iterator<Category> it = children.iterator();
        while (it.hasNext()) {
            Category child = it.next();
            if (child == null) {
                continue;
            }
            // If the child is inactive, remove it from its parent’s children list.
            if (!child.isActive()) {
                it.remove();
                removedCount++;
            } else {
                // If the child is active, continue traversing its subtree.
                stack.add(child);
            }
        }
    }
    return removedCount;
}

protected int removeUnusedNodes() {
    if (root == null) {
        return 0;
    }
    // If the root itself is inactive, remove the entire tree.
    if (!root.isActive()) {
        int removed = countSubtree(root);
        root = null;
        return removed;
    }
    // Recursively remove inactive nodes from the tree.
    return removeUnusedNodesRec(root);
}

private int removeUnusedNodesRec(Category node) {
    java.util.Iterator<Category> it = node.getChildren().iterator();
    int removed = 0;
    while (it.hasNext()) {
        Category child = it.next();
        if (!child.isActive()) {
            it.remove(); // remove the inactive child
            removed += countSubtree(child); // count all nodes in that subtree
        } else {
            removed += removeUnusedNodesRec(child); // recurse on active child
        }
    }
    return removed;
}

private int countSubtree(Category node) {
    int count = 1; // count the node itself
    for (Category child : node.getChildren()) {
        count += countSubtree(child);
    }
    return count;
