protected GraphPath<V,E> edgeSetToTour(Set<E> tour,Graph<V,E> graph){
    if (tour == null || graph == null){
        throw new IllegalArgumentException("tour and graph must not be null");
    }
    if (tour.isEmpty()){
        List<E> emptyEdges = Collections.emptyList();
        List<V> emptyVertices = Collections.emptyList();
        return new AbstractGraphPath<>(graph, null, null, emptyEdges, emptyVertices, 0.0);
    }
    Set<E> remaining = new HashSet<>(tour);
    List<E> edgeList = new ArrayList<>(tour.size());
    List<V> vertexList = new ArrayList<>(tour.size() + 1);

    E firstEdge = remaining.iterator().next();
    V start = graph.getEdgeSource(firstEdge);
    V current = start;
    vertexList.add(start);

    while (!remaining.isEmpty()){
        boolean found = false;
        Iterator<E> it = remaining.iterator();
        while (it.hasNext()){
            E e = it.next();
            V u = graph.getEdgeSource(e);
            V v = graph.getEdgeTarget(e);
            if (u.equals(current)){
                edgeList.add(e);
                vertexList.add(v);
                current = v;
                it.remove();
                found = true;
                break;
            } else if (v.equals(current)){
                edgeList.add(e);
                vertexList.add(u);
                current = u;
                it.remove();
                found = true;
                break;
            }
        }
        if (!found){
            throw new IllegalArgumentException("Edge set does not form a connected tour");
        }
    }

    if (!start.equals(current)){
        vertexList.add(start);
    }

    double weight = 0.0;
    for (E e : edgeList){
        weight += graph.getEdgeWeight(e);
    }

    return new AbstractGraphPath<>(graph, start, current, edgeList, vertexList, weight);
}

