private Pair<List<Integer>,Long> computeSuffixSum(List<Integer> bounds){
    List<Integer> suffixList = new ArrayList<>();
    long totalSum = 0L;
    if (bounds == null || bounds.isEmpty()){
        return new Pair<>(suffixList, Long.valueOf(totalSum));
    }
    // Compute total sum and collect suffix sums
    int size = bounds.size();
    suffixList = new ArrayList<>(Collections.nCopies(size, 0));
    long suffix = 0L;
    for (int i = size - 1; i >= 0; i--){
        int val = bounds.get(i) == null ? 0 : bounds.get(i);
        totalSum += val;
        suffix += val;
        // cast to int, clamping if out of range
        int suffixInt = (int) suffix;
        suffixList.set(i, suffixInt);
    }
    return new Pair<>(suffixList, Long.valueOf(totalSum));
}

private Pair<List<Integer>, Long> computeSuffixSum(List<Integer> bounds){
    if (bounds == null){
        throw new IllegalArgumentException("bounds must not be null");
    }
    int size = bounds.size();
    List<Integer> suffixSum = new ArrayList<>(size);
    long totalSum = 0;
    for (int i = size - 1; i >= 0; i--){
        int value = bounds.get(i);
        totalSum += value;
        // cast to int; overflow will wrap around, which is acceptable for a suffix sum of ints
        suffixSum.add(0, (int) totalSum);
    }
    return new Pair<>(suffixSum, totalSum);
}

private Pair<List<Integer>,Long> computeSuffixSum(List<Integer> bounds){
