private Pair<List<Integer>, Long> computeSuffixSum(List<Integer> bounds) {
    // Handle null or empty input gracefully
    if (bounds == null || bounds.isEmpty()) {
        return new Pair<>(new ArrayList<Integer>(), 0L);
    }

    // Compute total sum using long to prevent overflow
    long totalSum = 0L;
    for (Integer val : bounds) {
        if (val != null) {
            totalSum += val;
        }
    }

    // Compute suffix sums
    List<Integer> suffix = new ArrayList<>(bounds.size());
    long runningSum = 0L;
    for (int i = bounds.size() - 1; i >= 0; i--) {
        Integer val = bounds.get(i);
        if (val != null) {
            runningSum += val;
        }
        // Cast to int for the List<Integer> element; overflow will wrap around
        suffix.add(0, (int) runningSum);
    }

    return new Pair<>(suffix, totalSum);
}

