public static final <V>void reverse(V[] arr,int from,int to){
    if (arr == null) throw new NullPointerException("Array cannot be null");
    if (from < 0 || to >= arr.length || from > to) throw new IllegalArgumentException("Invalid from/to indices");
    for (int i = from, j = to; i < j; i++, j--){
        V temp = arr[i];
        arr[i] = arr[j];
        arr[j] = temp;
    }
}

public static final <V> void reverse(V[] arr, int from, int to) {
    if (arr == null) {
        throw new NullPointerException("Array must not be null");
    }
    int length = arr.length;
    if (from < 0 || to >= length) {
        throw new IndexOutOfBoundsException(
                "Index requested out of bounds. from: " + from + ", to: " + to + ", length: " + length);
    }
    if (from > to) {
        // No operation needed if the range is invalid (from > to)
        return;
    }
    int i = from;
    int j = to;
    while (i < j) {
        V temp = arr[i];
        arr[i] = arr[j];
        arr[j] = temp;
        i++;
        j--;
    }
}

public static final <V>void reverse(V[] arr,int from,int to){
    if (arr==null) throw new IllegalArgumentException("Array cannot be null");
    if (from<0 || to>=arr.length) throw new IllegalArgumentException("Index out of bounds");
    if (from>to) return;
    int i=from;
    int j=to;
    while(i<j){
        V temp=arr[i];
        arr[i]=arr[j];
        arr[j]=temp;
        i++;
        j--;
    }
}

public static final <V> void reverse(V[] arr,int from,int to){
    if (arr==null){
        throw new IllegalArgumentException("Array must not be null");
    }
    if (arr.length==0){
        return;
    }
    if (from<0){
        throw new IndexOutOfBoundsException("From index out of bounds: " + from);
    }
    if (to>=arr.length){
        throw new IndexOutOfBoundsException("To index out of bounds: " + to);
    }
    if (from>to){
        return;
    }
    int i=from, j=to;
    while (i<j){
        V tmp=arr[i];
        arr[i]=arr[j];
        arr[j]=tmp;
        i++; j--;
    }
}

private void moveAllListNodes(DoublyLinkedList<E> list) {
    if (list == null) {
        throw new NullPointerException("list");
    }
    if (list == this) {
        return;
    }
    if (list.isEmpty()) {
        return;
    }
    // Link the two lists together
    if (this.isEmpty()) {
        this.head = list.head;
        this.tail = list.tail;
    } else {
        list.tail.next = this.head;
        this.head.prev = list.tail;
        this.head = list.head;
    }
    // Update the size
    this.size += list.size;
    // Clear the source list
    list.head = null;
    list.tail = null;
    list.size = 0;
}

private void moveAllListNodes(DoublyLinkedList<E> list){
    if (list == null) {
        return;
    }
    // Retrieve the first node of the source list
    ListNode<E> current = list.getHead();
    while (current != null) {
        // Save reference to the next node before we detach the current one
        ListNode<E> next = current.getNext();
        try {
            // Atomically remove the node from the source list
            list.removeListNode(current);
            // Then add it to this list
            this.addListNode(current);
        } catch (Exception e) {
            // If something goes wrong, break out and rethrow as unchecked
            throw new RuntimeException("Failed to move list node", e);
        }
        // Move to the next node
        current = next;
    }
}

