    }
    try {
        // Move nodes one by one until the source list is empty.
        while (!list.isEmpty()) {
            // Retrieve the first node from the source list.
            ListNode<E> node = list.getFirst();
            if (node == null) {
                break; // Safety check in case getFirst returns null.
            }
            // Remove the node from the source list.
            list.removeListNode(node);
            // Add the same node to the current list.
            addListNode(node);
        }
    } catch (Exception ex) {
        // If any exception occurs during the transfer, we swallow it.
        // In production code, logging or rethrowing might be preferred.
    }
}

