private static boolean startsWith(final String str,final String prefix,final boolean ignoreCase){
    if (str == null && prefix == null) return true;
    if (str == null || prefix == null) return false;
    if (ignoreCase) {
        if (prefix.length() > str.length()) return false;
        return str.regionMatches(true, 0, prefix, 0, prefix.length());
    }
    return str.startsWith(prefix);
}

private static boolean startsWith(final String str,final String prefix,final boolean ignoreCase){
    if (str == null) {
        return prefix == null;
    }
    if (prefix == null) {
        return false;
    }
    int len = prefix.length();
    if (len > str.length()) {
        return false;
    }
    return str.regionMatches(ignoreCase, 0, prefix, 0, len);
}

private static boolean startsWith(final String str, final String prefix, final boolean ignoreCase) {
    // If both are null, consider it a match
    if (str == null && prefix == null) {
        return true;
    }
    // If one is null and the other is not, cannot match
    if (str == null || prefix == null) {
        return false;
    }
    // If prefix is longer than the string, it cannot start with the prefix
    if (prefix.length() > str.length()) {
        return false;
    }
    if (ignoreCase) {
        return str.regionMatches(true, 0, prefix, 0, prefix.length());
    } else {
        return str.startsWith(prefix);
    }
}

private static boolean startsWith(final String str, final String prefix, final boolean ignoreCase){ 
    // If either string is null, only return true if both are null
    if(str == null || prefix == null){ 
        return str == null && prefix == null; 
    } 
    // Empty prefix is always matched
    if(prefix.isEmpty()){ 
        return true; 
    } 
    // If prefix is longer than the string, cannot match
    if(str.length() < prefix.length()){ 
        return false; 
    }
    // Delegate to regionMatches for efficient case‑insensitive comparison
    if(ignoreCase){ 
        return str.regionMatches(true, 0, prefix, 0, prefix.length()); 
    } else { 
        return str.startsWith(prefix); 
    } 
}

