public void putAllWriteable(BeanMap map) {
    if (map == null) {
        throw new IllegalArgumentException("map must not be null");
    }
    for (Object key : map.keySet()) {
        if (key == null) {
            continue; // skip null keys
        }
        try {
            // Check that the source has a readable value and the target has a writable property
            if (map.isReadableObject(key) && this.isWritableObject(key)) {
                Object value = map.get(key);
                this.put(key, value);
            }
        } catch (Exception e) {
            // Ignore any property that cannot be read or written
        }
    }
}

