        String key = (String) keyObj;
        try {
            // Try to read the value from the source BeanMap.
            Object value = map.get(key);
            // If reading succeeded, attempt to write it into this BeanMap.
            this.put(key, value);
        } catch (Exception e) {
            // Ignore properties that are read‑only (cannot be read from the source)
            // or write‑only (cannot be set on this BeanMap).
        }
    }
}

public void putAllWriteable(BeanMap map){
