        return;
    }
    try {
        for (String prop : map.propertyNames()) {
            if (!map.isWritable(prop) || !this.isWritable(prop)) {
                continue;
            }
            Object value;
            try {
                value = map.get(prop);
            } catch (Exception e) {
                // Skip properties that cannot be read
                continue;
            }
            try {
                this.set(prop, value);
            } catch (Exception e) {
                // Skip properties that cannot be written
            }
        }
    } catch (Exception e) {
        // In case of unexpected errors, just exit silently
    }
}

