public static void selectRow(int row, JTable table, JScrollPane pane) {
    if (table == null || pane == null) {
        throw new IllegalArgumentException("Table and pane must not be null");
    }
    if (row < 0 || row >= table.getRowCount()) {
        throw new IllegalArgumentException("Row index out of bounds: " + row);
    }
    try {
        Runnable task = new Runnable() {
            @Override
            public void run() {
                try {
                    // Select the row and the first column to ensure the cell is focused
                    table.setRowSelectionInterval(row, row);
                    table.setColumnSelectionInterval(0, 0);
                    // Make the row visible in the table viewport
                    Rectangle cellRect = table.getCellRect(row, 0, true);
                    if (cellRect != null) {
                        table.scrollRectToVisible(cellRect);
                        // Sync the JScrollPane's view position with the table's
                        Point viewPos = pane.getViewport().getViewPosition();
                        if (viewPos != null) {
                            viewPos.y = cellRect.y;
                            pane.getViewport().setViewPosition(viewPos);
                        }
                    }
                    // Delay repaint until the selection and scrolling have completed
                    SwingUtilities.invokeLater(() -> {
                        try {
                            table.repaint();
                            pane.revalidate();
                            pane.repaint();
                        } catch (Exception e) {
                            // swallow
                        }
                    });
                } catch (Exception e) {
                    // swallow
                }
            }
        };
        if (SwingUtilities.isEventDispatchThread()) {
            task.run();
        } else {
            SwingUtilities.invokeLater(task);
        }
    } catch (Exception e) {
        // Log or rethrow as unchecked if necessary
    }
}

