public ByteVector putInt(final int intValue){
    final int required = pos + 4;
    if (required > len){
        int newLen = Math.max(len << 1, required);
        if (newLen == 0) newLen = required;
        byte[] newVec = new byte[newLen];
        System.arraycopy(vec, 0, newVec, 0, len);
        vec = newVec;
        len = newLen;
    }
    vec[pos++] = (byte) ((intValue >> 24) & 0xFF);
    vec[pos++] = (byte) ((intValue >> 16) & 0xFF);
    vec[pos++] = (byte) ((intValue >> 8) & 0xFF);
    vec[pos++] = (byte) (intValue & 0xFF);
    return this;
}

public ByteVector putInt(final int intValue){
    // Ensure the internal buffer can hold an additional 4 bytes
    if (vector == null) {
        vector = new byte[4];
        used = 0;
    }
    int required = used + 4;
    if (required > vector.length) {
        int newSize = Math.max(vector.length * 2, required);
        byte[] newVector = new byte[newSize];
        System.arraycopy(vector, 0, newVector, 0, used);
        vector = newVector;
    }
    // Write the int in big-endian order
    vector[used]     = (byte) (intValue >> 24);
    vector[used + 1] = (byte) (intValue >> 16);
    vector[used + 2] = (byte) (intValue >> 8);
    vector[used + 3] = (byte) intValue;
    used += 4;
    return this;
}

public ByteVector putInt(final int intValue){
    int len = this.len;
    byte[] buf = this.buf;
    if ((len += 4) > buf.length){
        buf = this.buf = new byte[Math.max(len, buf.length << 1)];
    }
    buf[len - 4] = (byte)(intValue >> 24);
    buf[len - 3] = (byte)(intValue >> 16);
    buf[len - 2] = (byte)(intValue >> 8);
    buf[len - 1] = (byte)intValue;
    this.len = len;
    return this;
}

public ByteVector putInt(final int intValue){
    if (cursor + 4 > buf.length) {
        int newCap = Math.max(buf.length << 1, cursor + 4);
        byte[] newBuf = new byte[newCap];
        System.arraycopy(buf, 0, newBuf, 0, cursor);
        buf = newBuf;
    }
    buf[cursor++] = (byte) (intValue >>> 24);
    buf[cursor++] = (byte) (intValue >>> 16);
    buf[cursor++] = (byte) (intValue >>> 8);
    buf[cursor++] = (byte) intValue;
    return this;
}

public static boolean arrayequals(byte[] a, byte[] b, int count) {
    // Handle null arrays
    if (a == null || b == null) {
        return false;
    }
    // Negative count does not make sense
    if (count < 0) {
        return false;
    }
    // If count exceeds either array length, they cannot be equal in that range
    if (count > a.length || count > b.length) {
        return false;
    }
    // Compare byte by byte
    for (int i = 0; i < count; i++) {
        if (a[i] != b[i]) {
            return false;
        }
    }
    return true;
}

public static boolean arrayequals(byte[] a,byte[] b,int count){
    if (a == null || b == null) {
        return false;
    }
    if (count < 0) {
        throw new IllegalArgumentException("count must be non-negative");
    }
    if (count > a.length || count > b.length) {
        return false;
    }
    for (int i = 0; i < count; i++) {
        if (a[i] != b[i]) {
            return false;
        }
    }
    return true;
}

public static boolean arrayequals(byte[] a,byte[] b,int count){
    // If count is non-positive, no bytes to compare; consider arrays equal.
    if(count <= 0){
        return true;
    }
    // If either array is null or shorter than count, they cannot be equal.
    if(a == null || b == null || a.length < count || b.length < count){
        return false;
    }
    // Compare byte by byte
    for(int i = 0; i < count; i++){
        if(a[i] != b[i]){
            return false;
        }
    }
    return true;
}

public void abbreviate(final int nameStart,final StringBuffer buf){
    if (buf == null) {
        return;
    }
    String fullName = this.getName(); // Assumes existence of getName() that returns the full name
    if (fullName == null) {
        return;
    }
    if (nameStart < 0) {
        throw new IllegalArgumentException("nameStart cannot be negative");
    }
    if (nameStart > fullName.length()) {
        // nothing to abbreviate
        return;
    }
    String remaining = fullName.substring(nameStart);
    if (remaining.isEmpty()) {
        return;
    }
    // Split the remaining string on '.' or '/' separators
    String[] parts = remaining.split("[./]");
    for (int i = 0; i < parts.length; i++) {
        String part = parts[i];
        if (part.isEmpty()) {
            continue;
        }
        if (i < parts.length - 1) {
            // Append the first character of the intermediate component followed by a separator
            buf.append(part.charAt(0));
            buf.append('.');
        } else {
            // Append the last component in full form
            buf.append(part);
        }
    }
}

public void abbreviate(final int nameStart, final StringBuffer buf){
    if (buf == null) {
        throw new IllegalArgumentException("Buffer must not be null");
    }
    String full = buf.toString();
    if (nameStart < 0 || nameStart > full.length()) {
        throw new IllegalArgumentException("nameStart out of bounds");
    }
    // Determine the end of the name segment: stop at whitespace or typical path separators
    int end = nameStart;
    while (end < full.length() && full.charAt(end) != ' '
            && full.charAt(end) != '/'
            && full.charAt(end) != '\\'
            && full.charAt(end) != '.') {
        end++;
    }
    if (nameStart == end) {
        // No name found; nothing to abbreviate
        return;
    }
    String name = full.substring(nameStart, end);
    String abbr;
    if (name.length() <= 3) {
        abbr = name;
    } else {
        // Keep a few characters at start and end, replace the middle with ellipsis
        int keep = Math.max(1, name.length() / 4);
        String first = name.substring(0, keep);
        String last = name.substring(name.length() - keep);
        abbr = first + "..." + last;
    }
    buf.append(abbr);
}

public void abbreviate(final int nameStart, final StringBuffer buf){
    if (buf == null) {
        return;
    }
    int len = buf.length();
    if (nameStart < 0) {
        return;
    }
    if (nameStart > len) {
        nameStart = len;
    }
    String name = buf.toString();
    StringBuilder abbr = new StringBuilder();
    int i = 0;
    // abbreviate all segments before nameStart
    while (i < nameStart) {
        char c = name.charAt(i);
        if (c == '.' || c == '/') {
            i++;
            continue;
        }
        // start of a segment
        abbr.append(c);
        i++;
        while (i < nameStart && name.charAt(i) != '.' && name.charAt(i) != '/') {
            i++;
        }
        abbr.append('.');
    }
    // remove trailing dot if present
    if (abbr.length() > 0 && abbr.charAt(abbr.length() - 1) == '.') {
        abbr.setLength(abbr.length() - 1);
    }
    // append the unchanged remainder from nameStart
    abbr.append(name.substring(nameStart));
    buf.setLength(0);
    buf.append(abbr);
}

public void abbreviate(final int nameStart,final StringBuffer buf){
    try {
        String name = this.name; // assume the class has a field `name`
        if (name == null) {
            return;
        }
        if (nameStart < 0 || nameStart > name.length()) {
            return;
        }
        String sub = name.substring(nameStart);
        String[] parts = sub.split("\\.");
        for (int i = 0; i < parts.length; i++) {
            String part = parts[i];
            if (!part.isEmpty()) {
                buf.append(part.charAt(0));
                if (i < parts.length - 1) {
                    buf.append('.');
                }
            }
        }
    } catch (Exception e) {
        // silently ignore any unexpected errors
    }
}

