    if (size <= 1) {
        return true;
    }
    List<V> list = new ArrayList<>(vertices);
    int n = list.size();
    for (int i = 0; i < n; i++) {
        V u = list.get(i);
        for (int j = i + 1; j < n; j++) {
            V v = list.get(j);
            // Check if an edge exists between u and v
            if (graph.getEdge(u, v) == null) {
                return false;
            }
        }
    }
    return true;
}

