private List<Integer> computeLowerBounds(List<K> keys){ 
    List<Integer> bounds = new ArrayList<>(); 
    if (keys == null) { 
        return bounds; 
    } 
    for (int i = 0; i < keys.size(); i++) { 
        bounds.add(0); // placeholder lower bound for each key 
    } 
    return bounds; 
}

private List<Integer> computeLowerBounds(List<K> keys){
    List<Integer> bounds = new ArrayList<>();
    if (keys == null || keys.isEmpty()) {
        return bounds;
    }
    // create a sorted copy of the keys
    List<K> sorted = new ArrayList<>(keys);
    sorted.sort((o1, o2) -> {
        if (o1 instanceof Comparable && o2 instanceof Comparable) {
            try {
                @SuppressWarnings("unchecked")
                Comparable<Object> c1 = (Comparable<Object>) o1;
                return c1.compareTo(o2);
            } catch (ClassCastException e) {
                return 0;
            }
        }
        return 0;
    });
    // comparator used for binary search
    Comparator<K> comp = (o1, o2) -> {
        if (o1 instanceof Comparable && o2 instanceof Comparable) {
            try {
                @SuppressWarnings("unchecked")
                Comparable<Object> c1 = (Comparable<Object>) o1;
                return c1.compareTo(o2);
            } catch (ClassCastException e) {
                return 0;
            }
        }
        return 0;
    };
    for (K key : keys) {
        int idx = Collections.binarySearch(sorted, key, comp);
        if (idx >= 0) {
            bounds.add(idx); // exact match
        } else {
            int insertionPoint = -idx - 1;
            int lower = insertionPoint - 1;
            bounds.add(lower); // may be -1 if key is smallest
        }
    }
    return bounds;
}

private List<Integer> computeLowerBounds(List<K> keys){
    List<Integer> lowerBounds = new ArrayList<>(keys.size());
    try{
        // Convert keys to Integer (requires K to be Integer)
        List<Integer> values = new ArrayList<>(keys.size());
        for(K k: keys){
            values.add((Integer)k);
        }
        // Sort values to determine lower bounds
        values.sort(Integer::compareTo);
        Map<Integer,Integer> lbMap = new HashMap<>();
        Integer prev = null;
        for(Integer val: values){
            if(prev==null){
                lbMap.put(val,Integer.MIN_VALUE);
            }else{
                lbMap.put(val,prev);
            }
            prev = val;
        }
        for(K k: keys){
            lowerBounds.add(lbMap.getOrDefault((Integer)k,Integer.MIN_VALUE));
        }
        return lowerBounds;
    }catch(ClassCastException e){
        // If K is not Integer, return empty list
        return new ArrayList<>();
    }
}

private List<Integer> computeLowerBounds(List<K> keys) {
    List<Integer> lowerBounds = new ArrayList<>();
    if (keys == null || keys.isEmpty()) {
        return lowerBounds;
    }
    for (int i = 0; i < keys.size(); i++) {
        K target = keys.get(i);
        int bestIdx = -1;
        for (int j = 0; j < keys.size(); j++) {
            K candidate = keys.get(j);
            if (candidate == null) {
                continue;
            }
            try {
                @SuppressWarnings("unchecked")
                int cmp = ((Comparable<? super K>) candidate).compareTo(target);
                if (cmp <= 0) {
                    if (j > bestIdx) {
                        bestIdx = j;
                    }
                }
            } catch (ClassCastException | NullPointerException e) {
                // Incompatible types or null target; skip this candidate
            }
        }
        lowerBounds.add(bestIdx);
    }
    return lowerBounds;
}

private List<Integer> computeLowerBounds(List<K> keys) {
    if (keys == null) {
        throw new IllegalArgumentException("keys list cannot be null");
    }
    List<Integer> lowerBounds = new ArrayList<>(keys.size());
    for (int i = 0; i < keys.size(); i++) {
        K current = keys.get(i);
        if (current == null) {
            lowerBounds.add(0);
            continue;
        }
        int currentHash = current.hashCode();
        int maxLower = Integer.MIN_VALUE;
        boolean found = false;
        for (int j = 0; j < keys.size(); j++) {
            if (j == i) {
                continue;
            }
            K other = keys.get(j);
            if (other == null) {
                continue;
            }
            int otherHash = other.hashCode();
            if (otherHash < currentHash && otherHash > maxLower) {
                maxLower = otherHash;
                found = true;
            }
        }
        lowerBounds.add(found ? maxLower : 0);
    }
    return lowerBounds;
}

private void pop(final String descriptor){
    if (descriptor == null || descriptor.isEmpty()){
        throw new IllegalArgumentException("descriptor must not be null or empty");
    }
    try{
        if (descriptor.charAt(0) == '('){ // Method descriptor
            int i = 1;
            while (i < descriptor.length() && descriptor.charAt(i) != ')'){
                int end = parseType(descriptor, i);
                if (isReference(descriptor, i, end)){
                    outputFrameStack.pop();
                }
                i = end;
            }
        }else{ // Single type descriptor
            int end = parseType(descriptor, 0);
            if (isReference(descriptor, 0, end)){
                outputFrameStack.pop();
            }
        }
    }catch(IndexOutOfBoundsException | IllegalArgumentException e){
        throw new IllegalArgumentException("Invalid descriptor: "+descriptor, e);
    }
}

private int parseType(String s, int index){
    int i = index;
    while (s.charAt(i) == '['){ // Array descriptor
        i++;
    }
    char c = s.charAt(i);
    if (c == 'L'){ // Object descriptor
        i++;
        while (s.charAt(i) != ';'){
            i++;
        }
        i++; // consume ';'
    }else{ // Primitive descriptor
        i++;
    }
    return i;
}

private boolean isReference(String s, int start, int end){
    int i = start;
    while (i < end && s.charAt(i) == '['){ // Skip array brackets
        i++;
