private void pop(final String descriptor) {
    if (descriptor == null || descriptor.isEmpty()) {
        return;
    }
    int count = 0;
    int i = 0;
    try {
        if (descriptor.charAt(0) == '(') {
            // method descriptor
            i = 1;
            while (i < descriptor.length()) {
                char c = descriptor.charAt(i);
                if (c == ')') {
                    break;
                }
                if (c == '[') {
                    // consume all '['
                    while (i < descriptor.length() && descriptor.charAt(i) == '[') {
                        i++;
                    }
                    if (i >= descriptor.length()) {
                        throw new IllegalArgumentException("Invalid descriptor: " + descriptor);
                    }
                    char base = descriptor.charAt(i);
                    i++; // consume base type char
                    if (base == 'L') {
                        // object type, consume until ';'
                        while (i < descriptor.length() && descriptor.charAt(i) != ';') {
                            i++;
                        }
                        if (i >= descriptor.length() || descriptor.charAt(i) != ';') {
                            throw new IllegalArgumentException("Invalid descriptor: " + descriptor);
                        }
                        i++; // consume ';'
                    }
                    count++;
                } else if (c == 'L') {
                    // object type
                    i++;
                    while (i < descriptor.length() && descriptor.charAt(i) != ';') {
                        i++;
                    }
                    if (i >= descriptor.length() || descriptor.charAt(i) != ';') {
                        throw new IllegalArgumentException("Invalid descriptor: " + descriptor);
                    }
                    i++; // consume ';'
                    count++;
                } else {
                    // primitive type
                    i++;
                    count++;
                }
            }
            // ignore return type after ')'
        } else {
            // single type descriptor
            char c = descriptor.charAt(0);
            if (c == '[') {
                // array type
                while (i < descriptor.length() && descriptor.charAt(i) == '[') {
                    i++;
                }
                if (i >= descriptor.length()) {
                    throw new IllegalArgumentException("Invalid descriptor: " + descriptor);
                }
                char base = descriptor.charAt(i);
                i++; // consume base type
                if (base == 'L') {
                    while (i < descriptor.length() && descriptor.charAt(i) != ';') {
                        i++;
                    }
                    if (i >= descriptor.length() || descriptor.charAt(i) != ';') {
                        throw new IllegalArgumentException("Invalid descriptor: " + descriptor);
                    }
                    i++; // consume ';'
                }
                count = 1;
            } else if (c == 'L') {
                // object type
                i++;
                while (i < descriptor.length() && descriptor.charAt(i) != ';') {
                    i++;
                }
                if (i >= descriptor.length() || descriptor.charAt(i) != ';') {
                    throw new IllegalArgumentException("Invalid descriptor: " + descriptor);
                }
                i++; // consume ';'
                count = 1;
