private void pop(final String descriptor) {
    if (descriptor == null || descriptor.isEmpty()) {
        return;
    }
    int i = 0;
    int len = descriptor.length();
    try {
        if (descriptor.charAt(0) == '(') {
            // method descriptor – pop argument types
            i = 1;
            while (i < len && descriptor.charAt(i) != ')') {
                i = consumeType(descriptor, i);
                outputFrameStack.pop(); // remove one abstract type from the output stack
            }
        } else {
            // field descriptor – pop the field type
            i = consumeType(descriptor, i);
            outputFrameStack.pop();
        }
    } catch (NoSuchElementException e) {
        throw new IllegalStateException("Attempted to pop from an empty output frame stack", e);
    }
}

private int consumeType(String desc, int start) {
    int i = start;
    char c = desc.charAt(i);
    // Array types: skip all '[' characters
    while (c == '[') {
        i++;
        c = desc.charAt(i);
    }
    // Object types: skip until ';'
    if (c == 'L') {
        i++;
        while (i < desc.length() && desc.charAt(i) != ';') {
            i++;
        }
        // move past ';'
        i++;
    } else {
        // Primitive types: single character ('I', 'J', 'B', 'S', 'C', 'Z', 'D', 'F', 'V')
        i++;
    }
    return i;
}

