private List<Integer> computeUpperBounds(List<K> keys){
    if (keys == null) {
        throw new NullPointerException("keys must not be null");
    }
    int size = keys.size();
    List<Integer> bounds = new ArrayList<>(size);
    // Check if all non-null elements are Comparable
    boolean allComparable = true;
    for (K key : keys) {
        if (key != null && !(key instanceof Comparable)) {
            allComparable = false;
            break;
        }
    }
    if (!allComparable) {
        // If keys are not comparable, return zeros as a safe fallback
        for (int i = 0; i < size; i++) {
            bounds.add(0);
        }
        return bounds;
    }
    // Prepare a sorted copy of the keys (ignoring nulls)
    @SuppressWarnings("unchecked")
    List<Comparable<? super K>> sorted = new ArrayList<>(size);
    for (K key : keys) {
        if (key != null) {
            sorted.add((Comparable<? super K>) key);
        }
    }
    Collections.sort(sorted);
    // Find upper bound index for each key
    for (K key : keys) {
        if (key == null) {
            bounds.add(0);
            continue;
        }
        @SuppressWarnings("unchecked")
        Comparable<? super K> compKey = (Comparable<? super K>) key;
        int index = Collections.binarySearch(sorted, compKey);
        if (index < 0) {
            index = -index - 1; // insertion point
        }
        bounds.add(index);
    }
    return bounds;
}

private List<Integer> computeUpperBounds(List<K> keys) { 
    List<Integer> upperBounds = new ArrayList<>(); 
    if (keys == null) { 
        return upperBounds; 
    } 
    for (K key : keys) { 
        if (key == null) { 
            upperBounds.add(null); 
            continue; 
        } 
        if (key instanceof Integer) { 
            Integer val = (Integer) key; 
            if (val == Integer.MAX_VALUE) { 
                upperBounds.add(val); 
            } else { 
                upperBounds.add(val + 1); 
            } 
        } else { 
            throw new IllegalArgumentException("Unsupported key type: " + key.getClass()); 
        } 
    } 
    return upperBounds; 
}

