public static String applyRelativePath(String path, String relativePath){
    if (path == null) {
        return relativePath == null ? null : relativePath;
    }
    if (relativePath == null) {
        return path;
    }
    // Split the base path
    String[] baseParts = path.split("/");
    ArrayDeque<String> stack = new ArrayDeque<>();
    boolean isAbsolute = path.startsWith("/");
    for (String part : baseParts) {
        if (part.isEmpty() || part.equals(".")) {
            continue;
        }
        stack.offerLast(part);
    }
    // Process the relative path
    String[] relParts = relativePath.split("/");
    for (String part : relParts) {
        if (part.isEmpty() || part.equals(".")) {
            continue;
        }
        if (part.equals("..")) {
            if (!stack.isEmpty()) {
                stack.pollLast();
            }
        } else {
            stack.offerLast(part);
        }
    }
    // Reconstruct the final path
    StringBuilder result = new StringBuilder();
    if (isAbsolute) {
        result.append("/");
    }
    Iterator<String> it = stack.iterator();
    while (it.hasNext()) {
        result.append(it.next());
        if (it.hasNext()) {
            result.append("/");
        }
    }
    // If result is empty, return "." as relative to current location
    return result.length() == 0 ? "." : result.toString();
}

public static String applyRelativePath(String path, String relativePath) {
    if (path == null || relativePath == null) {
        return null;
    }
    try {
        boolean isAbsolute = path.startsWith("/");
        Deque<String> parts = new ArrayDeque<>();

        // Process base path
        for (String part : path.split("/")) {
            if (part.isEmpty() || part.equals(".")) {
                continue;
            }
            if (part.equals("..")) {
                if (!parts.isEmpty()) parts.removeLast();
                continue;
            }
            parts.addLast(part);
        }

        // Process relative path
        for (String part : relativePath.split("/")) {
            if (part.isEmpty() || part.equals(".")) {
                continue;
            }
            if (part.equals("..")) {
                if (!parts.isEmpty()) parts.removeLast();
                continue;
            }
            parts.addLast(part);
        }

        String result = String.join("/", parts);
        if (isAbsolute) {
            // Ensure leading slash
            result = "/" + result;
            // Handle case of root only
            if (result.length() > 1 && result.endsWith("/")) {
                result = result.substring(0, result.length() - 1);
            }
        }
        // If result is empty and path was absolute, return "/"
        if (result.isEmpty() && isAbsolute) {
            return "/";
        }
        return result;
    } catch (Exception e) {
        // In case of unexpected errors, return null
        return null;
    }
}

public static String applyRelativePath(String path,String relativePath){
    if (path == null || relativePath == null){
        throw new IllegalArgumentException("path and relativePath must not be null");
    }
    // Try using NIO first, fallback to manual resolution on failure
    try{
        java.nio.file.Path base = java.nio.file.Paths.get(path);
        java.nio.file.Path parent;
        if (java.nio.file.Files.isDirectory(base)){
            parent = base;
        }else{
            parent = base.getParent();
            if (parent == null){
                // path looks like a file without a parent, treat whole as base
                parent = base;
            }
        }
        java.nio.file.Path resolved = parent.resolve(relativePath).normalize();
        String result = resolved.toString().replace(java.io.File.separatorChar, '/');
        // Ensure leading '/' for absolute paths on non-UNIX systems
        if (java.io.File.separatorChar != '/' && result.startsWith("\\")){
            result = result.replace("\\", "/");
        }
        return result;
    }catch (Exception e){
        boolean absolute = path.startsWith("/");
        String[] baseParts = path.split("/");
        java.util.List<String> stack = new java.util.ArrayList<>();
        for (String part : baseParts){
            if (part.isEmpty()) continue;
            stack.add(part);
        }
        String[] relParts = relativePath.split("/");
        for (String part : relParts){
            if (part.isEmpty() || part.equals(".")) continue;
            if (part.equals("..")){
                if (!stack.isEmpty()){
                    stack.remove(stack.size() - 1);
                }
            }else{
                stack.add(part);
            }
        }
        StringBuilder sb = new StringBuilder();
        if (absolute) sb.append("/");
        for (int i = 0; i < stack.size(); i++){
            if (i > 0) sb.append("/");
            sb.append(stack.get(i));
        }
        return sb.toString();
    }
}

public static String applyRelativePath(String path,String relativePath){
    if(path==null||relativePath==null){
        throw new IllegalArgumentException("path and relativePath must not be null");
    }
    // Use java.nio.file to resolve and normalize the path
    java.nio.file.Path base = java.nio.file.Paths.get(path);
    java.nio.file.Path resolved = base.resolve(relativePath);
    java.nio.file.Path normalized = resolved.normalize();
    return normalized.toString();
}

