    if (lastDot == -1) {
        return -1;
    }
    int lastSepUnix = filename.lastIndexOf('/');
    int lastSepWindows = filename.lastIndexOf('\\');
    int lastSep = Math.max(lastSepUnix, lastSepWindows);
    return lastSep > lastDot ? -1 : lastDot;
}

public boolean isExpired(long timestamp, long expiredThreshold) {
    if (expiredThreshold <= 0) {
        return true;
    }
    try {
        long now = System.currentTimeMillis();
        return now - timestamp > expiredThreshold;
    } catch (Exception e) {
        // If any unexpected exception occurs, treat as expired to avoid leaking
        return true;
    }
}

public boolean isExpired(long timestamp,long expiredThreshold){
    // Validate threshold
    if (expiredThreshold <= 0) {
        return false;
    }
    try {
        long currentTime = System.currentTimeMillis();
        // If the current time is not past the allowed threshold since last update,
        // the metric is still fresh.
        return (currentTime - timestamp) >= expiredThreshold;
    } catch (Exception e) {
        // In case of any unexpected runtime issue, conservatively keep the metric
        return false;
    }
}

