public int readTag() throws IOException {
    int tag = 0;
    int shift = 0;
    for (int i = 0; i < 5; i++) {
        int b = input.read();
        if (b == -1) {
            // End of input → return zero to indicate EOF
            return 0;
        }
        tag |= (b & 0x7F) << shift;
        if ((b & 0x80) == 0) {
            return tag;
        }
        shift += 7;
    }
    // If we get here, the varint is malformed (more than 5 bytes)
    throw new IOException("Malformed varint");
}

