    int firstByte = input.read();
    if (firstByte == -1) {
        // End of file reached; protocol allows tags to end anywhere.
        return 0;
    }
    // Decode a varint32 from the input.
    int result = firstByte & 0x7F;
    if ((firstByte & 0x80) == 0) {
        return result;
    }
    int shift = 7;
    while (true) {
        int nextByte = input.read();
        if (nextByte == -1) {
            // Unexpected EOF while reading a tag – treat as end of stream.
            return 0;
        }
        result |= (nextByte & 0x7F) << shift;
        if ((nextByte & 0x80) == 0) {
            break;
        }
        shift += 7;
        // Protect against malformed tag that exceeds 32 bits.
        if (shift > 35) {
            throw new MalformedInputException("Malformed varint tag");
        }
    }
    return result;
}

public int readTag() throws IOException {
    int raw = read();
    if (raw == -1) {
        return 0;
    }
    int result = raw & 0x7F;
    if ((raw & 0x80) == 0) {
        return result;
    }
    int shift = 7;
    while (shift < 32) {
        raw = read();
        if (raw == -1) {
            throw new EOFException("Malformed Varint");
        }
        result |= (raw & 0x7F) << shift;
        if ((raw & 0x80) == 0) {
            return result;
        }
        shift += 7;
    }
    throw new IOException("Varint too long");
}

